function frUnder100(n) {
  if (n < 17) return FR_ONES[n];
  if (n < 20) return 'dix-' + FR_ONES[n - 10];
  var t = Math.floor(n / 10), u = n % 10;
  if (t === 7 || t === 9) { u += 10; }
