}
function huntGrid(level) {
  var li = levelIndex(level);
  // The kinds by level: add 2 / add 3 / multiply 2 / pairs to 100.
  var kinds = li === 0 ? ['add2', 'add2', 'add3'] : li === 1 ? ['add2', 'add3', 'mul2'] : ['add3', 'mul2', 'add100', 'mul2'];
